{
  "headline": "Prioritize indoor air quality and mask up for outdoor travel",
  "summary": "Today's air quality is {{level.name}} with an AQI of {{aqi.now}}. Running air purifiers can reduce your exposure by {{impact.buy_hepa_purifier.pct}}, and the best time for outdoor activities is between {{best.start}} and {{best.end}}.",
  "cards": [
    {
      "actionId": "buy_hepa_purifier",
      "title": "Invest in a HEPA air purifier",
      "why": "Continuous mechanical filtration is the most effective way to reduce indoor PM2.5 exposure.",
      "when": "Run it continuously, especially during sleeping and home hours.",
      "steps": [
        "Close bedroom doors to concentrate filtration in occupied spaces.",
        "Avoid using ionizer functions, as they can produce ozone."
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Schedule errands during the best air quality window",
      "why": "Reducing time spent outdoors during high pollution periods minimizes exposure.",
      "when": "Plan outdoor tasks between {{best.start}} and {{best.end}}.",
      "steps": [
        "Group multiple errands into a single trip.",
        "Check air quality forecasts before leaving home."
      ]
    },
    {
      "actionId": "cooking_ventilation",
      "title": "Ensure proper ventilation during cooking",
      "why": "Cooking can release significant indoor pollutants. Proper ventilation captures these emissions.",
      "when": "Always use your kitchen exhaust fan or open windows when cooking.",
      "steps": [
        "Turn on the exhaust fan before you start cooking.",
        "Keep the fan on for a while after you finish cooking."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for a community-wide no-burning policy",
      "why": "Reducing local sources of smoke, like open burning, benefits everyone's air quality.",
      "when": "Discuss this at your next resident welfare association meeting.",
      "steps": [
        "Share information about the health impacts of burning.",
        "Propose alternative waste management solutions."
      ]
    },
    {
      "actionId": "wfh_on_worst_day",
      "title": "Work from home on severe air quality days",
      "why": "Avoiding commutes on high pollution days significantly cuts down on exposure and emissions.",
      "when": "Implement this when air quality reaches {{level.name}} or worse.",
      "steps": [
        "Coordinate with your employer to enable remote work.",
        "Use the time saved to engage in indoor activities."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "adult",
      "note": "Consider reducing strenuous outdoor activities when air quality is {{level.name}}."
    },
    {
      "group": "pregnant",
      "note": "Minimize exposure to outdoor pollution by staying indoors as much as possible."
    }
  ],
  "tradeoffs": [
    "Working from home on bad air days reduces your commute exposure, but ensure you have good indoor air filtration.",
    "Shifting errands to the best air quality window may require schedule adjustments."
  ]
}
